#!/usr/bin/env python3
"""Regenerate ground truth for CSX-141_Q1."""

from __future__ import annotations

import html
import json
import re
from collections import Counter
from pathlib import Path
from typing import Any


TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PACKAGE_ROOT = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / "CSX-141"

REPORT = "data/event_reports/event_reports_005_Locked_anchor_report_NOAA_NWS.html"
ANCHOR = "data/event_reports/event_reports_004_Locked_event_anchor_March_31-April_1_2023_U.S._tornado_outbreak.json"


def load_json(rel_path: str) -> Any:
    return json.loads((PACKAGE_ROOT / rel_path).read_text(encoding="utf-8-sig"))


def clean_html_text(raw: str) -> str:
    text = html.unescape(raw.replace("&nbsp;", " "))
    text = re.sub(r"<[^>]+>", " ", text)
    return re.sub(r"\s+", " ", text).strip()


def first_int(pattern: str, text: str) -> int:
    match = re.search(pattern, text, flags=re.IGNORECASE)
    if not match:
        raise ValueError(f"pattern not found: {pattern}")
    return int(match.group(1))


def pct(numerator: int, denominator: int) -> float:
    return round(numerator / denominator * 100, 1)


def build_rubric() -> dict[str, Any]:
    criteria = [
        {
            "name": "Final ledger state",
            "points": 4,
            "description": "Gives the exact final label dense_lower_rated_short_window_subset and tests_passed = 4.",
            "partial_credit": "Award 2-3 points for the correct label with an incorrect pass count, or the correct pass count with a near-equivalent label.",
        },
        {
            "name": "Local tornado and EF ledger",
            "points": 4,
            "description": "Reports 22 local tornadoes, EF-1 as the modal rating, and EF counts EF-U: 1, EF-0: 6, EF-1: 12, EF-2: 3.",
            "partial_credit": "Award 2-3 points for the right total and modal rating but incomplete counts; award 1 point for only the total.",
        },
        {
            "name": "Percentage calculations",
            "points": 4,
            "description": "Computes 81.8%, 93.2%, and 15.1% with correct numerators and denominators.",
            "partial_credit": "Award 2-3 points for two correct percentages; award 1 point for one correct percentage.",
        },
        {
            "name": "Threshold tests",
            "points": 3,
            "description": "Applies all four thresholds correctly, including the inclusive 10% to 20% local-share band.",
            "partial_credit": "Award 1-2 points for evaluating two or three thresholds correctly.",
        },
        {
            "name": "Timing and rating pattern",
            "points": 3,
            "description": "Connects the 24-hour concentration and lower-rated local mix to the final ledger state.",
            "partial_credit": "Award 1-2 points for using only timing or only rating mix.",
        },
        {
            "name": "Compact output discipline",
            "points": 2,
            "description": "Returns the requested fields and avoids added casualty, loss, or track-geometry assertions not derived from the computed ledger.",
            "partial_credit": "Award 1 point for a mostly correct but verbose or partly missing output.",
        },
    ]
    total = sum(item["points"] for item in criteria)
    if total != 20:
        raise ValueError(f"rubric points sum to {total}, expected 20")
    return {"total_points": total, "criteria": criteria}


def main() -> None:
    raw_html = (PACKAGE_ROOT / REPORT).read_text(encoding="utf-8", errors="ignore")
    report_text = clean_html_text(raw_html)
    anchor = load_json(ANCHOR)

    heading_matches = re.findall(
        r"<strong>(\d+)\.\)\s*(.*?)\s*:\s*(EF-[0-5U])</strong>",
        raw_html,
        flags=re.IGNORECASE | re.DOTALL,
    )
    ratings = [rating.upper() for _, _, rating in heading_matches]
    rating_counter = Counter(ratings)
    rating_counts = {key: rating_counter[key] for key in sorted(rating_counter)}
    modal_rating, modal_count = rating_counter.most_common(1)[0]

    national_total = first_int(r"A total of\s+(\d+)\s+tornadoes were confirmed nationally", report_text)
    local_total = first_int(r"A total of\s+(\d+)\s+tornadoes were confirmed in the NWS Chicago forecast area", report_text)
    within_24h = first_int(r"(\d+)\s+of these\s+\d+\s+tornadoes occurred within the span of 24 hours", report_text)

    if sum(rating_counts.values()) != local_total:
        raise ValueError("parsed local EF count does not equal local tornado total")

    ef0_ef1_count = rating_counts.get("EF-0", 0) + rating_counts.get("EF-1", 0)
    ef0_ef1_share = pct(ef0_ef1_count, local_total)
    national_24h_share = pct(within_24h, national_total)
    local_national_share = pct(local_total, national_total)

    tests = {
        "local_count_ge_20": local_total >= 20,
        "ef0_ef1_share_ge_75": ef0_ef1_share >= 75.0,
        "national_24h_share_ge_90": national_24h_share >= 90.0,
        "local_national_share_10_to_20": 10.0 <= local_national_share <= 20.0,
    }
    tests_passed = sum(1 for value in tests.values() if value)
    final_label = "dense_lower_rated_short_window_subset" if tests_passed == 4 else "ledger_threshold_miss"

    primary_gt = {
        "answer": final_label,
        "local_tornado_count": local_total,
        "modal_rating": modal_rating,
        "ef0_ef1_share_pct": ef0_ef1_share,
        "national_24h_share_pct": national_24h_share,
        "local_national_share_pct": local_national_share,
        "tests_passed": tests_passed,
        "threshold_result": "all_four_pass" if tests_passed == 4 else "not_all_pass",
    }

    computed = {
        "schema_version": "1.0",
        "task_id": "CSX-141_Q1",
        "event_id": "CSX-141",
        "task_type": "numeric",
        "target_family": "numeric_diagnosis",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "key_values": {
            "event_name": "March 31-April 1, 2023 U.S. tornado outbreak",
            "analysis_region": "NWS Chicago forecast area",
            "event_window": {
                "start_date": anchor["temporal_window"]["start_date"],
                "end_date": anchor["temporal_window"]["end_date"],
            },
            "rating_counts": rating_counts,
            "modal_rating_count": modal_count,
            "national_tornado_count": national_total,
            "tornadoes_within_24h": within_24h,
            "ef0_ef1_count": ef0_ef1_count,
            "tests": tests,
            "tolerances": {
                "local_tornado_count": 0,
                "ef0_ef1_share_pct": 0.1,
                "national_24h_share_pct": 0.1,
                "local_national_share_pct": 0.1,
                "tests_passed": 0,
            },
        },
        "rubric": build_rubric(),
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [REPORT, ANCHOR],
        },
    }

    (TASK_DIR / "computed_gt.json").write_text(
        json.dumps(computed, indent=2, ensure_ascii=False) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
